// ============================================================
// QuantScatter Host 端: tiling 计算 + 分批 launch
// 分核模式: 每核一行 (模式B), 当 B > MAX_CORES 时分批 launch
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_quant_scatter_fp16.h"
#include "aclrtlaunch_quant_scatter_bf16.h"

#include <torch/extension.h>

namespace ascend_kernel {

// bufferCoefficient = 30 (从设计文档 UB 分配表推导)
constexpr int64_t BUFFER_COEFFICIENT = 30;
constexpr int64_t UB_ALIGN_BYTES = 32;

at::Tensor quant_scatter(
        const at::Tensor &input,
        const at::Tensor &indices,
        const at::Tensor &updates,
        const at::Tensor &quant_scales,
        const c10::optional<at::Tensor> &quant_zero_points,
        int64_t axis,
        int64_t quant_axis,
        c10::string_view reduce) {

    // ---- 输入校验 ----
    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1,
                "quant_scatter: input must be on NPU device");
    TORCH_CHECK(indices.device().type() == at::DeviceType::PrivateUse1,
                "quant_scatter: indices must be on NPU device");
    TORCH_CHECK(updates.device().type() == at::DeviceType::PrivateUse1,
                "quant_scatter: updates must be on NPU device");
    TORCH_CHECK(quant_scales.device().type() == at::DeviceType::PrivateUse1,
                "quant_scatter: quant_scales must be on NPU device");

    TORCH_CHECK(input.scalar_type() == at::kChar || input.scalar_type() == at::kByte,
                "quant_scatter: input must be int8");
    TORCH_CHECK(indices.scalar_type() == at::kInt,
                "quant_scatter: indices must be int32");
    TORCH_CHECK(updates.scalar_type() == at::kHalf ||
                updates.scalar_type() == at::kBFloat16,
                "quant_scatter: updates must be float16 or bfloat16");

    int64_t ndim = input.dim();
    int64_t up_ndim = updates.dim();

    // 规范化 axis
    if (axis < 0) axis += ndim;
    if (quant_axis < 0) quant_axis += up_ndim;
    TORCH_CHECK(axis >= 0 && axis < ndim,
                "quant_scatter: axis out of range");
    TORCH_CHECK(quant_axis >= 0 && quant_axis < up_ndim,
                "quant_scatter: quant_axis out of range");

    // 判断是否为 bfloat16 updates
    bool isBf16 = (updates.scalar_type() == at::kBFloat16);

    // ---- 连续化 + 类型转换 ----
    // host 端将 scales 和 zero_points 统一转为 float32
    at::Tensor inputContig = input.contiguous();
    at::Tensor indicesContig = indices.contiguous();
    at::Tensor updatesContig = updates.contiguous();

    // scales → float32
    at::Tensor scalesFp32 = quant_scales.contiguous();
    if (scalesFp32.scalar_type() != at::kFloat) {
        scalesFp32 = scalesFp32.to(at::kFloat);
    }

    // zero_points → float32 (如果有)
    bool hasZp = quant_zero_points.has_value();
    at::Tensor zpFp32;
    if (hasZp) {
        zpFp32 = quant_zero_points.value().contiguous();
        if (zpFp32.scalar_type() != at::kFloat) {
            zpFp32 = zpFp32.to(at::kFloat);
        }
    }

    // ---- 输出: clone input ----
    at::Tensor output = inputContig.clone();

    // ---- 维度参数 ----
    int64_t B = updatesContig.size(0);  // 批次数
    int64_t D = updatesContig.size(quant_axis);  // 量化轴大小 (内轴)

    // 计算 output 的 stride
    // output shape = input.shape, contiguous
    auto outStrides = output.strides();
    int64_t outStride0 = outStrides[0];   // B 维 stride = product of dims[1:]
    int64_t outStrideAxis = outStrides[axis];  // axis 维 stride

    // 计算 updates 的 stride
    auto upStrides = updatesContig.strides();
    int64_t upStride0 = upStrides[0];        // B 维 stride
    int64_t upStrideQuantAxis = upStrides[quant_axis];  // quant_axis 维 stride

    // scales/zp stride (contiguous [1, 1, D] 或广播形状)
    auto scStrides = scalesFp32.strides();
    int64_t scStride0 = scStrides.size() > 0 ? scStrides[0] : 0;
    int64_t scStrideLast = scStrides.size() > 0 ? scStrides.back() : 1;

    int64_t zpStride0 = 0;
    int64_t zpStrideLast = 1;
    if (hasZp) {
        auto zpStrides = zpFp32.strides();
        zpStride0 = zpStrides.size() > 0 ? zpStrides[0] : 0;
        zpStrideLast = zpStrides.size() > 0 ? zpStrides.back() : 1;
    }

    // ---- 平台参数 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // ---- UB 级 tiling ----
    // tileLength = UB_SIZE / bufferCoefficient, 32B 对齐
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
    int64_t maxTileElements = ubSizeLimit / BUFFER_COEFFICIENT;
    int64_t alignElements = UB_ALIGN_BYTES / 1;  // int8 为 1 byte/element → align 32 elements
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength > D) {
        tileLength = D;  // D 很小时用 D 本身
        // 重新对齐
        tileLength = (tileLength / alignElements) * alignElements;
    }
    if (tileLength < alignElements) {
        tileLength = alignElements;
    }

    // ---- 类型大小 ----
    int64_t upDtypeSize = updatesContig.element_size();  // 2 for half/bf16
    int64_t scDtypeSize = scalesFp32.element_size();     // 4 for float32
    int64_t zpDtypeSize = hasZp ? zpFp32.element_size() : 4;

    // ---- 分批 launch ----
    int64_t processed = 0;
    while (processed < B) {
        int64_t batchSize = std::min(B - processed, coreNum);
        uint32_t blockDim = static_cast<uint32_t>(batchSize);
        if (blockDim < 1) blockDim = 1;

        int64_t rowStart = processed;
        int64_t rowCount = batchSize;

        // 左值局部变量 (EXEC_KERNEL_CMD 要求)
        int64_t innerDimVal = D;
        int64_t tileLengthVal = tileLength;
        int64_t outStride0Val = outStride0;
        int64_t outStride1Val = outStrideAxis;
        int64_t upStride0Val = upStride0;
        int64_t scStride0Val = scStride0;
        int64_t scStride2Val = scStrideLast;
        int64_t zpStride0Val = zpStride0;
        int64_t zpStride2Val = zpStrideLast;
        int64_t hasZpVal = hasZp ? 1 : 0;
        int64_t upDTypeSizeVal = upDtypeSize;

        if (isBf16) {
            EXEC_KERNEL_CMD(quant_scatter_bf16, blockDim,
                            output, indicesContig, updatesContig,
                            scalesFp32, zpFp32, inputContig,
                            rowStart, rowCount, innerDimVal,
                            tileLengthVal, outStride0Val, outStride1Val,
                            upStride0Val, scStride0Val, scStride2Val,
                            zpStride0Val, zpStride2Val,
                            hasZpVal, upDTypeSizeVal);
        } else {
            EXEC_KERNEL_CMD(quant_scatter_fp16, blockDim,
                            output, indicesContig, updatesContig,
                            scalesFp32, zpFp32, inputContig,
                            rowStart, rowCount, innerDimVal,
                            tileLengthVal, outStride0Val, outStride1Val,
                            upStride0Val, scStride0Val, scStride2Val,
                            zpStride0Val, zpStride2Val,
                            hasZpVal, upDTypeSizeVal);
        }

        processed += batchSize;
    }

    return output;
}

}  // namespace ascend_kernel
