 * Debug: Identity kernel - just copy updates to output at scatter position
 */
#include "kernel_operator.h"

using namespace AscendC;
constexpr int64_t BUF_NUM = 2;

extern "C" __global__ __aicore__ void quant_scatter_debug(
        GM_ADDR output, GM_ADDR indices, GM_ADDR updates,
        GM_ADDR scales, GM_ADDR zeroPoints, GM_ADDR input,
        int64_t rowStart, int64_t rowCount, int64_t innerDim,
        int64_t tileLength, int64_t outStride0, int64_t outStride1,
        int64_t upStride0, int64_t scStride0, int64_t scStride2,
        int64_t zpStride0, int64_t zpStride2,
        int64_t hasZp, int64_t upDtypeSize) {

    int64_t blockIdx = GetBlockIdx();
    if (blockIdx >= rowCount) return;

    int64_t rowIdx = rowStart + blockIdx;
    GlobalTensor<int8_t> outGm;
    outGm.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(output));
    GlobalTensor<int32_t> idxGm;
    idxGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(indices));
    GlobalTensor<half> upGm;
    upGm.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(updates));
    GlobalTensor<float> scGm;
    scGm.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scales));

    int64_t idxVal = static_cast<int64_t>(idxGm.GetValue(rowIdx));

    TPipe pipe;
    TQue<TPosition::VECIN, BUF_NUM> inQ;
    TQue<TPosition::VECOUT, BUF_NUM> outQ;
    pipe.InitBuffer(inQ, BUF_NUM, tileLength * sizeof(half));
    pipe.InitBuffer(outQ, BUF_NUM, tileLength * sizeof(half));

    int64_t tileNum = (innerDim + tileLength - 1) / tileLength;
    int64_t tailLen = innerDim - (tileNum - 1) * tileLength;

    for (int64_t ti = 0; ti < tileNum; ++ti) {
        int64_t curLen = (ti == tileNum - 1) ? tailLen : tileLength;
        int64_t offset = ti * tileLength;

        // CopyIn: GM→UB
        LocalTensor<half> inLocal = inQ.AllocTensor<half>();
        DataCopyExtParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(curLen * sizeof(half));
        cp.srcStride = 0;
        cp.dstStride = 0;
        DataCopyPadExtParams<half> pp;
        pp.isPad = false;
        DataCopyPad(inLocal, upGm[rowIdx * upStride0 + offset], cp, pp);
        inQ.EnQue(inLocal);

        // Compute: identity
        LocalTensor<half> inData = inQ.DeQue<half>();
        LocalTensor<half> outData = outQ.AllocTensor<half>();
        // Just copy via Duplicate or simple API
        // Use Duplicate for test
        Duplicate<half>(outData, (half)0.0f, curLen);
        outQ.EnQue(outData);
        inQ.FreeTensor(inData);

        // CopyOut: UB→GM
        LocalTensor<half> outLocal = outQ.DeQue<half>();
        DataCopyExtParams cp2;
        cp2.blockCount = 1;
        cp2.blockLen = static_cast<uint32_t>(curLen * sizeof(half));
        cp2.srcStride = 0;
        cp2.dstStride = 0;
        int64_t outOff = rowIdx * outStride0 + idxVal * outStride1 + offset;
        DataCopyPad(outGm[outOff], outLocal, cp2);
        outQ.FreeTensor(outLocal);
    }
}
