// ============================================================
// QuantScatter Kernel: 简化版 - 直接输出固定值 50 来隔离问题
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

template<typename UpT>
class QuantScatterKernel {
public:
    __aicore__ inline QuantScatterKernel() {}

    __aicore__ inline void Init(GM_ADDR output, GM_ADDR indices, GM_ADDR updates,
                                  GM_ADDR scales, GM_ADDR zeroPoints, GM_ADDR input,
                                  int64_t rowStart, int64_t rowCount, int64_t innerDim,
                                  int64_t tileLength, int64_t outStride0, int64_t outStride1,
                                  int64_t upStride0, int64_t scStride0, int64_t scStride2,
                                  int64_t zpStride0, int64_t zpStride2,
                                  int64_t hasZp, int64_t upDtypeSize) {
        rowStart_ = rowStart;
        rowCount_ = rowCount;
        innerDim_ = innerDim;
        tileLength_ = tileLength;
        outStride0_ = outStride0;
        outStride1_ = outStride1;
        upStride0_ = upStride0;
        scStride0_ = scStride0;
        scStride2_ = scStride2;
        zpStride0_ = zpStride0;
        zpStride2_ = zpStride2;
        hasZp_ = hasZp;

        outputGm.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(output));
        indicesGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(indices));
        updatesGm.SetGlobalBuffer(reinterpret_cast<__gm__ UpT *>(updates));
        scalesGm.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scales));
        zpGm.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(zeroPoints));
        inputGm.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(input));

        pipe.InitBuffer(upBuf, tileLength_ * sizeof(UpT));
        pipe.InitBuffer(scBuf, tileLength_ * sizeof(float));
        if (hasZp_) {
            pipe.InitBuffer(zpBuf, tileLength_ * sizeof(float));
        }
        pipe.InitBuffer(calcBuf, tileLength_ * sizeof(float) + tileLength_ * sizeof(int16_t));
        pipe.InitBuffer(outBuf, tileLength_ * sizeof(int8_t));
    }

    __aicore__ inline void Process() {
        int64_t blockIdx = GetBlockIdx();
        if (blockIdx >= rowCount_) return;

        int64_t rowIdx = rowStart_ + blockIdx;
        int64_t idxVal = static_cast<int64_t>(indicesGm.GetValue(rowIdx));

        int64_t tileNum = (innerDim_ + tileLength_ - 1) / tileLength_;
        int64_t tailLen = innerDim_ - (tileNum - 1) * tileLength_;

        for (int64_t ti = 0; ti < tileNum; ++ti) {
            int64_t curLen = (ti == tileNum - 1) ? tailLen : tileLength_;
            int64_t off = ti * tileLength_;

            // --- CopyIn ---
            {
                LocalTensor<UpT> up = upBuf.Get<UpT>();
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(UpT));
                cp.srcStride = 0; cp.dstStride = 0;
                DataCopyPadExtParams<UpT> pp; pp.isPad = false;
                DataCopyPad(up, updatesGm[rowIdx * upStride0_ + off], cp, pp);

                LocalTensor<float> sc = scBuf.Get<float>();
                DataCopyExtParams scp;
                scp.blockCount = 1;
                scp.blockLen = static_cast<uint32_t>(curLen * sizeof(float));
                scp.srcStride = 0; scp.dstStride = 0;
                DataCopyPadExtParams<float> spp; spp.isPad = false;
                DataCopyPad(sc, scalesGm[off * scStride2_], scp, spp);

                if (hasZp_) {
                    LocalTensor<float> zp = zpBuf.Get<float>();
                    DataCopyExtParams zcp;
                    zcp.blockCount = 1;
                    zcp.blockLen = static_cast<uint32_t>(curLen * sizeof(float));
                    zcp.srcStride = 0; zcp.dstStride = 0;
                    DataCopyPadExtParams<float> zpp; zpp.isPad = false;
                    DataCopyPad(zp, zpGm[off * zpStride2_], zcp, zpp);
                }
            }
            PipeBarrier<PIPE_ALL>();

            // --- Compute ---
            {
                LocalTensor<UpT> up = upBuf.Get<UpT>();
                LocalTensor<float> sc = scBuf.Get<float>();
                LocalTensor<float> cf = calcBuf.Get<float>();
                int64_t i16Off = tileLength_ * sizeof(float) / sizeof(int16_t);
                LocalTensor<int16_t> ci = calcBuf.Get<int16_t>(i16Off);
                LocalTensor<int8_t> out = outBuf.Get<int8_t>();

                // Cast up → fp32
                if constexpr (sizeof(UpT) < sizeof(float)) {
                    Cast(cf, up, RoundMode::CAST_NONE, curLen);
                }

                // Clip inf
                constexpr float IC = 1.0e15f;
                Mins(cf, cf, IC, curLen);
                Maxs(cf, cf, -IC, curLen);

                // DIV
                Div(cf, cf, sc, curLen);

                // ADD zp
                if (hasZp_) {
                    LocalTensor<float> zp = zpBuf.Get<float>();
                    Add(cf, cf, zp, curLen);
                }

                // CLAMP
                Mins(cf, cf, 127.0f, curLen);
                Maxs(cf, cf, -128.0f, curLen);

                // ROUND → int16
                Cast(ci, cf, RoundMode::CAST_RINT, curLen);

                // int16 → int8
                Cast(out, ci, RoundMode::CAST_NONE, curLen);
            }
            PipeBarrier<PIPE_ALL>();

            // --- CopyOut ---
            {
                LocalTensor<int8_t> out = outBuf.Get<int8_t>();
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = static_cast<uint32_t>(curLen * sizeof(int8_t));
                cp.srcStride = 0; cp.dstStride = 0;
                int64_t outOff = rowIdx * outStride0_ + idxVal * outStride1_ + off;
                DataCopyPad(outputGm[outOff], out, cp);
            }
            PipeBarrier<PIPE_ALL>();
        }
    }

private:
    TPipe pipe;
    TBuf<TPosition::VECIN> upBuf, scBuf, zpBuf;
    TBuf<TPosition::VECCALC> calcBuf;
    TBuf<TPosition::VECOUT> outBuf;
    GlobalTensor<int8_t> outputGm;
    GlobalTensor<int32_t> indicesGm;
    GlobalTensor<UpT> updatesGm;
    GlobalTensor<float> scalesGm, zpGm;
    GlobalTensor<int8_t> inputGm;
    int64_t rowStart_, rowCount_, innerDim_, tileLength_;
    int64_t outStride0_, outStride1_, upStride0_;
    int64_t scStride0_, scStride2_, zpStride0_, zpStride2_, hasZp_;
};


