        GM_ADDR o, GM_ADDR i, GM_ADDR u, GM_ADDR s, GM_ADDR z, GM_ADDR n,
        int64_t rs, int64_t rc, int64_t id, int64_t tl, int64_t os0, int64_t os1,
        int64_t us0, int64_t scs0, int64_t scs2, int64_t zps0, int64_t zps2,
        int64_t hz, int64_t uds) {
    QuantScatterKernel<half> k;
    k.Init(o,i,u,s,z,n,rs,rc,id,tl,os0,os1,us0,scs0,scs2,zps0,zps2,hz,uds);
    k.Process();
}

