// QuantScatter Host: 完成量化计算 + kernel 调度

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_quant_scatter.h"

#include <torch/extension.h>

namespace ascend_kernel {

constexpr int64_t UB_ALIGN_BYTES = 32;
// bufferCoefficient = 2 (int8 input double-buffered: 1 for inBuf)
// Actually just need single buffer: sizeof(int8) = 1 byte/element
constexpr int64_t BUFFER_COEFF = 2;  // 1 byte/elem, 2x for minimal double-buffer-like usage

at::Tensor quant_scatter(
        const at::Tensor &input,
        const at::Tensor &indices,
        const at::Tensor &updates,
        const at::Tensor &quant_scales,
        const c10::optional<at::Tensor> &quant_zero_points,
        int64_t axis,
        int64_t quant_axis,
        c10::string_view reduce) {

    // ---- 输入校验 ----
    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1, "input must be on NPU");
    TORCH_CHECK(indices.device().type() == at::DeviceType::PrivateUse1, "indices must be on NPU");
    TORCH_CHECK(updates.device().type() == at::DeviceType::PrivateUse1, "updates must be on NPU");
    TORCH_CHECK(quant_scales.device().type() == at::DeviceType::PrivateUse1, "scales must be on NPU");
    TORCH_CHECK(input.scalar_type() == at::kChar, "input must be int8");
    TORCH_CHECK(indices.scalar_type() == at::kInt, "indices must be int32");

    int64_t ndim = input.dim();
    int64_t up_ndim = updates.dim();
    if (axis < 0) axis += ndim;
    if (quant_axis < 0) quant_axis += up_ndim;

    // ---- 连续化 ----
    at::Tensor inputContig = input.contiguous();
    at::Tensor indicesContig = indices.contiguous();
    at::Tensor updatesContig = updates.contiguous();
    at::Tensor scalesContig = quant_scales.contiguous();
    bool hasZp = quant_zero_points.has_value();
    at::Tensor zpContig;
    if (hasZp) {
        zpContig = quant_zero_points.value().contiguous();
    }

    // ---- Host 端量化 ----
    // 扩展 scales 和 zp 到 updates 维度
    auto upFloat = updatesContig.to(at::kFloat);
    auto scFloat = scalesContig.to(at::kFloat);
    while (scFloat.dim() < upFloat.dim()) {
        scFloat = scFloat.unsqueeze(0);
    }
    auto divResult = upFloat / scFloat;
    if (hasZp) {
        auto zpFloat = zpContig.to(at::kFloat);
        while (zpFloat.dim() < upFloat.dim()) {
            zpFloat = zpFloat.unsqueeze(0);
        }
        divResult = divResult + zpFloat;
    }
    // round + clamp + to int8
    auto quantized = at::round(divResult).clamp(-128, 127).to(at::kChar);

    // ---- 输出 ----
    at::Tensor output = inputContig.clone();

    // ---- 维度参数 ----
    int64_t B = updatesContig.size(0);
    int64_t D = updatesContig.size(quant_axis);

    auto outStrides = output.strides();
    int64_t outStride0 = outStrides[0];
    int64_t outStrideAxis = outStrides[axis];

    auto qStrides = quantized.strides();
    int64_t qStride0 = qStrides[0];

    // ---- 平台参数 ----
    auto platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = (int64_t)platform->GetCoreNumAiv();
    uint64_t ubSize = 0;
    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // ---- UB tiling ----
    int64_t ubLimit = (int64_t)ubSize;
