// QuantScatter: Host does quantization, kernel does scatter copy only.
// Uses TQue for proper double-buffered GM↔UB DMA with VECIN/VECOUT direction.

#include "kernel_operator.h"
using namespace AscendC;

constexpr int64_t BUF_NUM = 2;

class QuantScatterKernel {
public:
    __aicore__ inline QuantScatterKernel() {}
    __aicore__ inline void Init(
            GM_ADDR output, GM_ADDR indices, GM_ADDR quantized,
            int64_t rowStart, int64_t rowCount, int64_t innerDim,
            int64_t tileLength, int64_t outStride0, int64_t outStride1,
            int64_t qStride0) {
        rowStart_ = rowStart; rowCount_ = rowCount; innerDim_ = innerDim;
        tileLength_ = tileLength; outStride0_ = outStride0; outStride1_ = outStride1;
        qStride0_ = qStride0;
        outGm_.SetGlobalBuffer((__gm__ int8_t*)output);
        idxGm_.SetGlobalBuffer((__gm__ int32_t*)indices);
        qGm_.SetGlobalBuffer((__gm__ int8_t*)quantized);
        pipe_.InitBuffer(inQ_, BUF_NUM, tileLength_ * sizeof(int8_t));
        pipe_.InitBuffer(outQ_, BUF_NUM, tileLength_ * sizeof(int8_t));
    }

    __aicore__ inline void Process() {
        int64_t bid = GetBlockIdx();
        if (bid >= rowCount_) return;
        int64_t row = rowStart_ + bid;
        int64_t iv = (int64_t)idxGm_.GetValue(row);

        int64_t tn = (innerDim_ + tileLength_ - 1) / tileLength_;
        int64_t tt = innerDim_ - (tn - 1) * tileLength_;

        for (int64_t t = 0; t < tn; ++t) {
            int64_t cl = (t == tn - 1) ? tt : tileLength_;
            int64_t to = t * tileLength_;

            // CopyIn: GM → VECIN
            {
                LocalTensor<int8_t> in = inQ_.AllocTensor<int8_t>();
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = (uint32_t)(cl * sizeof(int8_t));
                cp.srcStride = 0; cp.dstStride = 0;
                DataCopyPadExtParams<int8_t> pp; pp.isPad = false;
                DataCopyPad(in, qGm_[row * qStride0_ + to], cp, pp);
                inQ_.EnQue(in);
            }

            // CopyOut: VECOUT → GM
            {
                LocalTensor<int8_t> in = inQ_.DeQue<int8_t>();
                LocalTensor<int8_t> out = outQ_.AllocTensor<int8_t>();

                // Copy UB→UB via AscendC Copy
                uint32_t dB = (uint32_t)(((uint32_t)(cl * sizeof(int8_t)) + 31) / 32);
                uint64_t mask = ((uint64_t)dB > 128) ? 128 : dB;
                Copy(out, in, mask, 1, {1, 1, 8, 8});

                outQ_.EnQue(out);
                inQ_.FreeTensor(in);
            }

            // Write to output GM
            {
                LocalTensor<int8_t> out = outQ_.DeQue<int8_t>();
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = (uint32_t)(cl * sizeof(int8_t));
                cp.srcStride = 0; cp.dstStride = 0;
                int64_t oo = row * outStride0_ + iv * outStride1_ + to;
                DataCopyPad(outGm_[oo], out, cp);
                outQ_.FreeTensor(out);
            }
        }
    }

private:
    TPipe pipe_;
    TQue<TPosition::VECIN, BUF_NUM> inQ_;
    TQue<TPosition::VECOUT, BUF_NUM> outQ_;
    GlobalTensor<int8_t> outGm_, qGm_;
    GlobalTensor<int32_t> idxGm_;
    int64_t rowStart_, rowCount_, innerDim_, tileLength_;
    int64_t outStride0_, outStride1_, qStride0_;
};

