        rowStart_ = rowStart; rowCount_ = rowCount; innerDim_ = innerDim;
        tileLength_ = tileLength; outStride0_ = outStride0; outStride1_ = outStride1;
        qStride0_ = qStride0;
        outGm_.SetGlobalBuffer((__gm__ int8_t*)output);
        idxGm_.SetGlobalBuffer((__gm__ int32_t*)indices);
        qGm_.SetGlobalBuffer((__gm__ int8_t*)quantized);
        pipe_.InitBuffer(buf_, tileLength_ * sizeof(int8_t));
    }

    __aicore__ inline void Process() {
        int64_t bid = GetBlockIdx();
        if (bid >= rowCount_) return;
        int64_t row = rowStart_ + bid;
        int64_t iv = (int64_t)idxGm_.GetValue(row);

        int64_t tn = (innerDim_ + tileLength_ - 1) / tileLength_;
        int64_t tt = innerDim_ - (tn - 1) * tileLength_;

        for (int64_t t = 0; t < tn; ++t) {
            int64_t cl = (t == tn - 1) ? tt : tileLength_;
            int64_t to = t * tileLength_;

            // Load quantized tile from GM
            {
                LocalTensor<int8_t> local = buf_.Get<int8_t>();
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = (uint32_t)(cl * sizeof(int8_t));
                cp.srcStride = 0; cp.dstStride = 0;
                DataCopyPadExtParams<int8_t> pp; pp.isPad = false;
                DataCopyPad(local, qGm_[row * qStride0_ + to], cp, pp);
            }
            PipeBarrier<PIPE_ALL>();

            // Scatter write to output GM
            {
                LocalTensor<int8_t> local = buf_.Get<int8_t>();
                DataCopyExtParams cp;
                cp.blockCount = 1;
                cp.blockLen = (uint32_t)(cl * sizeof(int8_t));
                cp.srcStride = 0; cp.dstStride = 0;
                int64_t oo = row * outStride0_ + iv * outStride1_ + to;
