    GlobalTensor<int8_t> outGm_, qGm_;
    GlobalTensor<int32_t> idxGm_;
    int64_t rowStart_, rowCount_, innerDim_, tileLength_;
    int64_t outStride0_, outStride1_, qStride0_;
};

